={{ (() => {
  try {
    const r = JSON.parse($json.output[0].content[0].text);
    return Number.isInteger(r?.score) && r.score >= 0 && r.score <= 100
      ? r.score : -1;
  } catch {
    return -1;
  }
})() }}

={{ (() => {
  try {
    const r = JSON.parse($json.output[0].content[0].text);
    return typeof r?.reason === 'string' && r.reason.trim()
      ? r.reason.trim() : 'Invalid scoring response';
  } catch {
    return 'Invalid scoring response';
  }
})() }}

={{ (() => {
  try {
    const result = JSON.parse($json.output[0].content[0].text);
    return result !== null
      && typeof result === 'object'
      && !Array.isArray(result)
      && Number.isInteger(result.score)
      && result.score >= 0
      && result.score <= 100
      && typeof result.reason === 'string'
      && result.reason.trim().length > 0;
  } catch {
    return false;
  }
})() }}
